# Each entry: concept, implementation and testing, exercise, question, correct answer, distractors.
NOTES = {
'2.1.1': ('Functions must work using a keyboard interface without requiring precisely timed keystrokes. The limited exception concerns functions whose underlying operation genuinely depends on a movement path, not merely the way a developer chose to implement them.', 'Use native buttons and links and ensure custom controls respond to keyboard input. A signature-drawing function can depend on a path; entering text does not become path-dependent just because handwriting is offered. Test Tab, Shift+Tab, Enter, Space and arrow keys where appropriate.', 'Navigate a menu and complete a form without touching a pointer. Record every action that cannot be reached or activated, then replace one clickable noninteractive element with a button.', 'A custom menu opens only on mouse hover. What is the best correction?', 'Make it focusable and operable with keyboard controls', ['Remove its visible text', 'Require users to click faster', 'Disable all pointer input']),
'2.1.2': ('A user who moves focus into a component must be able to move away using the keyboard. An intentional focus loop inside a modal is not a trap if a keyboard user can close the modal and return to the page.', 'Provide conventional exit keys and a visible close control; if exiting requires an unusual method, explain it to the user. Test embedded widgets and dialogs as well as the surrounding page.', 'Open a dialog using only the keyboard, close it, and continue to the next page control. Document where focus goes after closing.', 'A dialog cycles focus internally but Escape and its Close button both work. What should you test next?', 'Close it by keyboard and verify focus can continue through the page', ['Remove keyboard support', 'Keep the dialog permanently open', 'Assume every focus loop is a failure']),
'2.1.3': ('This AAA criterion requires all functionality to be keyboard-operable without timing-dependent keystrokes and does not include the path-dependent exception in 2.1.1. It sets a higher target than the Level A baseline.', 'Design alternative workflows for tasks that normally use pointer paths; a drawing application might provide controls for creating and editing shapes by coordinates. Whether an alternative provides the same functionality requires careful evaluation.', 'Choose a drawing or map interface and outline a keyboard workflow for each operation, including moving, resizing, and confirming an object.', 'What distinguishes this AAA criterion from 2.1.1?', 'It does not provide the path-dependent exception', ['It only applies to forms', 'It permits timed keystrokes', 'It prohibits keyboard shortcuts']),
'2.1.4': ('Single-character shortcuts can fire accidentally when a speech user dictates text or when focus is unexpected. Shortcuts made solely from letters, punctuation, numbers or symbols need a safeguard.', 'Provide a way to turn the shortcut off, remap it to include a non-printable modifier, or activate it only while the relevant component has focus. Verify these options work after settings are saved.', 'Find a single-letter shortcut in a mock editor. Design and test one of the three allowed safeguards.', 'A site assigns the letter s as a global shortcut. Which safeguard is appropriate?', 'Let users disable it or remap it with a modifier', ['Hide the shortcut documentation', 'Trigger it whenever text is typed', 'Require users to speak more quietly']),
'2.2.1': ('Content-imposed time limits can prevent people from reading, using assistive technology, or recovering from interruptions. Users need control over qualifying time limits, subject to defined exceptions.', 'Offer a way to turn the limit off, adjust it to at least ten times the default, or warn before expiry and allow at least 20 seconds for a simple extension, at least ten times. Real-time, essential and longer-than-20-hour exceptions have specific conditions; do not assume every security timeout is automatically exempt.', 'Review a checkout timeout. Specify warning timing, extension control, repeat count and a test that preserves entered data.', 'Which warning-and-extension design meets the specified timing option?', 'Give at least 20 seconds to extend and allow at least ten extensions', ['Show a warning after expiration', 'Allow only one extension', 'Automatically submit an unfinished form']),
'2.2.2': ('Automatically moving, blinking or scrolling information running for more than five seconds alongside other content needs a pause, stop or hide mechanism unless essential. Automatically updating information alongside other content also needs control, without the five-second condition.', 'Provide a keyboard-operable pause or frequency control near the content. A motion control is not a substitute for evaluating flashing under 2.3.', 'Inspect an automatic carousel and a live news feed. Determine which controls each needs and verify the controls remain available by keyboard.', 'A news feed updates automatically alongside an article. What control can address it?', 'Let users pause the updates or control their frequency', ['Make the updates faster', 'Hide the control from keyboard users', 'Require all users to reload every second']),
'2.2.3': ('At AAA, timing is not an essential part of the activity, except for non-interactive synchronized media and real-time events. This is stronger than merely offering an extension under 2.2.1.', 'For self-paced quizzes, separate elapsed-time information from the ability to answer. Retain meaningful exceptions for genuinely real-time events rather than treating business preference as a technical necessity.', 'Redesign a timed practice quiz so that a learner can complete it at their own pace; explain whether a live auction is different.', 'Which is an appropriate design for a self-paced practice quiz?', 'Allow completion without a countdown deadline', ['End the attempt after 30 seconds', 'Offer only one short extension', 'Hide the remaining time']),
'2.2.4': ('Interruptions can disrupt concentration and assistive technology output. The AAA requirement lets users postpone or suppress interruptions except those involving an emergency.', 'Make non-emergency notifications configurable and avoid shifting focus to a promotion while a person is typing. Explain what has been suppressed and let the user retrieve it later.', 'Classify a promotional banner, a chat invitation and an emergency alert. Design controls for the non-emergency interruptions.', 'Which notification should generally be postponable or suppressible?', 'A non-emergency promotional message', ['An emergency warning', 'The current field label', 'A user-requested page heading']),
'2.2.5': ('If an authenticated session expires, users need to re-authenticate and continue their activity without losing data. Losing an unfinished application can be especially costly for users who need more time.', 'Preserve the in-progress state securely, return to the same step after login, and avoid submitting on the user’s behalf. Consider shared devices, retention policies and privacy when choosing storage.', 'Enter a multi-step form, force a session expiry, log back in and verify the draft and current step are restored.', 'What should happen after a session expires during a form?', 'After re-authentication, restore the activity without data loss', ['Clear the form immediately', 'Submit incomplete information', 'Force the user to start a different task']),
'2.2.6': ('Warn users about the period of inactivity that may cause loss of entered data, unless the data is preserved for more than 20 hours while the user takes no action.', 'Explain the actual inactivity duration before a user risks losing work. Saving a draft can reduce the risk, but its retention and privacy implications should be considered separately.', 'Write an inactivity warning for an unsaved form and verify it matches the application’s actual timeout behavior.', 'When is a warning about inactivity-related data loss required under this criterion?', 'When inactivity may cause data loss and the data is not preserved for more than 20 hours', ['Only after the data has already been lost', 'Only for decorative images', 'Never when a form has multiple steps']),
'2.3.1': ('Flashing content can trigger seizures. At Level A, content must not flash more than three times in any one second unless it is below both applicable general and red flash thresholds.', 'The thresholds depend on properties including the area and characteristics of the flash; visual inspection alone is not a reliable assessment. Prefer static feedback and use an appropriate flash analysis tool if flashing is unavoidable.', 'Replace a rapidly flashing error animation with static text and an icon. Explain why judging safety from a short casual glance is insufficient.', 'What is a safer alternative to a rapidly flashing error message?', 'Use a static, clearly labeled error indication', ['Increase the flashing area', 'Use rapid saturated red flashes', 'Assume all small flashes are safe without checking']),
'2.3.2': ('The AAA criterion prohibits more than three flashes in any one-second period; unlike 2.3.1, it does not offer the below-threshold alternative.', 'Remove rapid flashes from animations, advertisements and embedded media. Count changes using the WCAG definition of a flash and test the actual rendered content.', 'Compare a four-flash-per-second animation with a static notification and explain the AAA outcome.', 'How does 2.3.2 differ from 2.3.1?', 'It does not include the below-threshold alternative', ['It permits unlimited small flashes', 'It only applies to keyboard focus', 'It requires every page to animate']),
'2.3.3': ('Motion animation triggered by interaction can cause dizziness or nausea. At AAA it must be possible to disable it unless essential to the functionality or information.', 'Respect reduced-motion preferences where possible and offer a setting when needed. Replace a zooming transition with an immediate state change while retaining the content and controls.', 'Enable reduced motion, activate a menu and compare the interaction with its animated version. Confirm the same information remains available.', 'What is an appropriate alternative to a large animated zoom transition?', 'Offer a reduced-motion or disabled-animation mode', ['Make the zoom faster', 'Remove the destination content', 'Require a pointer to disable it']),
'2.4.1': ('Repeated navigation and other blocks force keyboard users to traverse the same material on each page. A bypass mechanism lets users reach the unique content efficiently.', 'Place a visible-on-focus skip link early in the page and connect it to the main content. Semantic landmarks and other mechanisms can also help; test the actual focus movement and reading position.', 'Tab from the browser into a page, activate its skip link and confirm that subsequent keyboard navigation starts at the main content.', 'What should a skip link help a user do?', 'Move past repeated navigation to the main content', ['Open every navigation item', 'Disable the page heading', 'Hide the main content']),
'2.4.2': ('A page title identifies the topic or purpose in browser tabs, history and assistive technology. Generic or repeated titles make pages difficult to distinguish.', 'Set a descriptive document title such as “Payment details – Store”. Update it after client-side route changes and include meaningful context when an error state changes the page.', 'Open three application pages in tabs and compare their titles. Rewrite ambiguous titles so each page can be identified without inspecting its body.', 'Which browser title best identifies a checkout step?', 'Payment details – Store', ['Home', 'Untitled', 'Page']),
'2.4.3': ('Sequential focus must preserve meaning and operability when order affects understanding or interaction. Visual layout, DOM order and script-driven focus can diverge.', 'Use a logical DOM order and avoid positive tabindex values as a shortcut. When opening a dialog, move focus into it and restore focus sensibly when it closes. Check responsive layouts and dynamically inserted errors.', 'Tab through a form and a dialog at desktop and mobile widths. Draw the focus sequence and correct any jumps that make the task confusing.', 'A form visually displays name then email, but focus jumps from email to an unrelated footer. What should be reviewed?', 'DOM order and any scripted focus changes', ['Only the background image', 'The server clock', 'The page filename']),
'2.4.4': ('Users need to understand where a link leads from its text or its programmatically determined context, subject to the general-ambiguity exception. Context must be available to assistive technology, not merely placed visually nearby.', 'Prefer descriptive text such as “Read the refund policy”. If the same short label appears in a structured list or table, test that its relevant context is actually associated and announced.', 'Inspect a list of “Read more” links. Rewrite them or verify their programmatic context identifies each destination.', 'Which link communicates its purpose most reliably?', 'Read the refund policy', ['Click here', 'More', 'Link']),
'2.4.5': ('People find pages in different ways. For a set of web pages, provide more than one way to locate each page, except pages that are results of or steps in a process.', 'Combine a consistent navigation system with search, a site map, or contextual links. Confirm that both methods really reach the intended page and are usable with keyboard and assistive technology.', 'Choose a help article and reach it through navigation and through search. Record any pages that have only one route.', 'Which combination can provide multiple ways to locate a help page?', 'Navigation and a working site search', ['Only a single menu item', 'A different background color', 'A longer URL']),
'2.4.6': ('Headings and labels should describe the topic or purpose of the section or control they identify. Accurate labels help users scan, navigate and avoid mistakes.', 'Use specific headings and associate form labels with their inputs. A heading saying “Billing address” communicates more than “Details”; a label should identify what belongs in the field.', 'Review a form with three fields labeled “Information”. Give each a specific label and check the accessible association.', 'Which label best describes an email field?', 'Email address', ['Information', 'Field', 'Enter']),
'2.4.7': ('Keyboard users need a visible indication of which control has focus. Without it, the next key press may activate an unknown control.', 'Avoid removing browser outlines without a clear replacement. Test :focus-visible across links, buttons and custom widgets against their backgrounds and in high-contrast modes.', 'Tab through a navigation bar and form. Identify controls with no visible indicator, then apply and retest a distinct outline.', 'What is an appropriate replacement for outline: none?', 'A clearly visible focus indicator on keyboard focus', ['No visible change', 'A hover-only color', 'A hidden tooltip']),
'2.4.8': ('At AAA, users can determine their location within a set of pages. Location cues help people understand their place in a larger site and return to nearby sections.', 'Use breadcrumbs, a current navigation item, or another clear indication as appropriate. Ensure the current state is communicated programmatically when applicable, for example with aria-current.', 'Inspect a three-level documentation site and add a breadcrumb that identifies the current page. Test how the current item is announced.', 'Which feature can help communicate location within a site?', 'A breadcrumb identifying the current page', ['An unrelated animation', 'A blank document title', 'Removing navigation']),
'2.4.9': ('At AAA, a mechanism allows link purpose to be identified from link text alone, except when purpose would be ambiguous to users generally. This supports users who navigate a list of links out of context.', 'Write self-contained link names such as “Download the annual report” instead of relying on a neighboring heading to explain “Download”. Check repeated links and accessible names.', 'Extract all links from a page into a list and rewrite any labels whose destinations are unclear in isolation.', 'Which link text can be understood without surrounding context?', 'Download the annual report', ['Download', 'Here', 'More']),
'2.4.10': ('Section headings organize written content and help readers navigate long documents. This criterion concerns sections within writing, rather than the names of interactive components.', 'Introduce meaningful section headings and use semantic heading elements where appropriate. A heading should identify the section, not merely create large decorative text.', 'Break a long help article into logical sections, add descriptive headings and inspect the resulting heading outline.', 'What is the primary purpose of section headings here?', 'Organize written content into understandable sections', ['Replace all form labels', 'Create decorative spacing only', 'Hide the article']),
'2.4.11': ('At AA, an author-created overlay must not entirely hide a component that has keyboard focus. Sticky headers, footers and floating banners can cover focused controls.', 'Account for overlays when scrolling focus into view, for example with suitable scroll padding. Check at zoomed sizes and with keyboard navigation; the criterion addresses the focused component, not just its outline.', 'Tab through a long page with a sticky footer and note whether each focused component is at least partly visible.', 'A sticky banner fully covers the focused button. What is the relevant issue?', 'Author-created content entirely obscures the focused component', ['The button has too much text', 'The page contains a footer', 'The browser has a title']),
'2.4.12': ('The AAA enhanced requirement is stricter than 2.4.11: no part of the focused component may be hidden by author-created content.', 'Test scroll position near sticky headers and footers and account for varying viewport sizes. A partially visible button may satisfy the minimum requirement but still fail this enhanced one.', 'Focus a button partly underneath a sticky header. Adjust scrolling so the whole component remains visible and compare the AA and AAA outcomes.', 'A focused button is partly covered by an author-created banner. What is the AAA concern?', 'Any part of the focused component is obscured', ['The component is not entirely hidden', 'The user used a keyboard', 'The page has a header']),
'2.4.13': ('At AAA, a visible focus indicator must provide an area at least as large as a two-CSS-pixel-thick perimeter of the unfocused component and a contrast ratio of at least 3:1 between the same pixels in focused and unfocused states, subject to defined exceptions.', 'A two-pixel outline is a useful starting point, not automatic proof: check its actual area and focused-versus-unfocused pixel contrast, including clipping and overlap. Exceptions cover certain unmodified user-agent indicators.', 'Measure a button’s indicator area and compare the same pixels before and after focus. Record whether it reaches both thresholds.', 'Which measurements are relevant to Focus Appearance?', 'Indicator area and contrast between the same focused and unfocused pixels', ['Only the page title', 'Only pointer target spacing', 'Animation duration']),
'2.5.1': ('Multipoint or path-based gestures must have a single-pointer alternative that does not require a path-based gesture, unless the gesture is essential. This helps users who cannot pinch or trace a precise path.', 'Offer plus and minus buttons for a pinch-to-zoom map and separate previous/next buttons for a swipe carousel. A simple pointer alternative is different from keyboard support, though both may be needed.', 'Test a swipe-only gallery using a single tap. Add and test a previous and next control.', 'What alternative can make a pinch-to-zoom map usable with a single pointer?', 'Provide tap-operated zoom buttons', ['Require a more precise pinch', 'Disable all map controls', 'Offer keyboard input only']),
'2.5.2': ('A pointer action that completes on press can be triggered accidentally before a user can move away. The criterion offers several ways to prevent or reverse unintended activation, with an essential-function exception.', 'For ordinary buttons, complete the action on release and permit the user to move away before release. Alternatively provide an appropriate undo, an up-event reversal, or meet another specified condition.', 'Press and hold a delete button, move the pointer away, then release. Confirm whether the delete is canceled and whether an undo is available.', 'How can a normal delete button support pointer cancellation?', 'Complete on release and allow abort before completion', ['Delete immediately on press with no recovery', 'Remove the button label', 'Require a faster press']),
'2.5.3': ('For controls with a visible text label, the accessible name must contain that visible text. Speech users often activate a control by saying the words they can see.', 'Prefer the visible wording at the beginning of the accessible name. If a button says “Search”, an aria-label of “Find items” alone can make voice activation unpredictable; test the computed accessible name.', 'Inspect a button labeled “Search” whose aria-label is “Find items”. Change its name to include the visible label and verify it in accessibility tools.', 'A button visibly says “Search”. Which accessible name includes its visible label?', 'Search products', ['Find items', 'Magnifying glass', 'Submit query']),
'2.5.4': ('When functionality is activated by moving a device or making a user motion, users generally need an alternative interface control and a way to disable motion activation. Supported-interface and essential-function exceptions are defined.', 'Provide a conventional undo button alongside shake-to-undo and let users turn shake activation off. Test accidental movement and ensure disabling motion does not remove the alternative.', 'Review a shake-to-undo feature. Add a visible undo control and a setting that disables shake activation.', 'How should a nonessential shake-to-undo feature be made more accessible?', 'Provide an undo control and allow shake activation to be disabled', ['Require a stronger shake', 'Remove undo completely', 'Automatically trigger on any movement']),
'2.5.5': ('The AAA enhanced target-size criterion generally requires pointer targets to be at least 44 by 44 CSS pixels, with defined exceptions including equivalent controls, inline targets, unmodified user-agent controls and essential presentation.', 'Measure the interactive hit area in CSS pixels, not just the icon graphic. Consider both dimensions and test adjacent controls on touch devices; spacing alone is not the general AAA size rule.', 'Measure a toolbar button’s hit area and increase it to 44 by 44 CSS pixels without changing the icon size. Review whether any exception applies.', 'What is the general AAA minimum pointer target size?', '44 by 44 CSS pixels', ['24 by 24 CSS pixels', '12 by 12 CSS pixels', 'Any size if colored']),
'2.5.6': ('Users may switch between touch, keyboard, pointer and assistive inputs on the same device. At AAA, content must not restrict platform input modalities except where essential, needed for security, or required by user settings.', 'Avoid disabling keyboard controls merely because touch is detected. Test a hybrid laptop with both touch and keyboard during the same session and respect the user’s settings.', 'On a hybrid device, operate a menu by touch and then by keyboard without reloading. Record any modality that becomes unavailable.', 'What is a suitable design for a touch-enabled laptop?', 'Keep keyboard and touch interaction available together', ['Disable keyboard when touch is detected', 'Require users to reload to change inputs', 'Ignore user input settings']),
'2.5.7': ('A dragging movement needs a single-pointer alternative that does not require dragging, unless dragging is essential or is unmodified user-agent functionality. Keyboard support alone does not satisfy this pointer-specific requirement.', 'For sortable cards, add a menu with Move up and Move down actions. For sliders, offer tap controls or a numeric entry where appropriate, while preserving the underlying operation.', 'Use a task board without dragging. Design and test a menu that moves a card between columns with taps.', 'What alternative addresses a draggable task card?', 'A tap-operated menu for moving the card', ['Keyboard support alone', 'A faster drag animation', 'Removing the card label']),
'2.5.8': ('The AA minimum target-size criterion generally requires targets of at least 24 by 24 CSS pixels, with specified exceptions for spacing, equivalent controls, inline targets, unmodified user-agent controls and essential presentation.', 'For an undersized target, check the actual spacing exception using 24-CSS-pixel diameter circles centered on the target bounds and their relationship to nearby targets. Merely adding a few pixels of margin is not automatically sufficient.', 'Measure adjacent icon buttons. Increase their hit areas or evaluate the spacing exception using the specified circles, then retest touch activation.', 'What is the general AA minimum target size before considering exceptions?', '24 by 24 CSS pixels', ['44 by 44 CSS pixels', '8 by 8 CSS pixels', 'Any size if the icon is recognizable'])
}

SCENARIOS = {
'2.1.1': ('A dashboard uses a div with an onclick handler for “Export”. It works with a mouse but is absent from the tab order. A keyboard user cannot download the report.', 'Use a native button with a click handler. Tab to it and activate it with Enter and Space. Then verify that the resulting download or dialog is available without a mouse.'),
'2.1.2': ('A third-party date picker accepts keyboard focus but consumes every Tab and Escape key. Users cannot reach the rest of the form.', 'Provide a standard exit and verify focus can leave the widget. If an unusual key combination is unavoidable, explain it before the user enters.'),
'2.1.3': ('A diagram editor offers only freehand pointer drawing, so a person who relies on keyboard input cannot create the same diagram.', 'Provide keyboard-accessible shape insertion, movement and editing. Evaluate whether these controls actually cover every supported operation rather than only basic navigation.'),
'2.1.4': ('In a video page the global “m” shortcut mutes audio while a speech user dictates an unrelated message. The action is unexpected and interrupts the task.', 'Offer a setting to disable or remap the character shortcut, or limit it to focus on the video component. Test typing and dictation outside that component.'),
'2.2.1': ('A registration form signs a user out five minutes after loading without warning and discards partially entered answers.', 'Before expiry offer a simple extension with at least 20 seconds to respond, repeatable at least ten times, or use another permitted option. Determine whether any claimed exception genuinely applies.'),
'2.2.2': ('An automatic carousel continually changes next to a sign-up form, while a nearby stock ticker refreshes on its own. The movement and updates interrupt reading.', 'Give users a pause control for the carousel and a pause or update-frequency control for the ticker. Test with keyboard and check the controls affect the actual content.'),
'2.2.3': ('A self-paced practice assessment requires every answer within thirty seconds, although its purpose is learning rather than a live contest.', 'Remove the countdown as a condition of completion. If displaying elapsed time is useful, ensure it does not end the activity or prevent answering.'),
'2.2.4': ('A promotional dialog appears while a learner is completing a difficult form and moves keyboard focus away from the current field.', 'Allow the learner to defer or suppress this non-emergency interruption and retrieve the message later. Do not suppress emergency warnings under this exception.'),
'2.2.5': ('A session expires while an applicant is halfway through a long application. After signing in again, the application is blank.', 'Preserve the in-progress state securely and restore the same task after successful authentication. Test the expiry and re-entry path without automatically submitting.'),
'2.2.6': ('An application silently deletes an unfinished draft after fifteen minutes of inactivity. A learner who pauses to consult notes returns to an empty form.', 'Inform the learner of the inactivity period that risks data loss, unless the actual preservation period meets the more-than-20-hours exception. Check that the warning matches system behavior.'),
'2.3.1': ('A large red error banner flashes rapidly to draw attention. A person with photosensitive epilepsy may be exposed before they can choose to stop it.', 'Use a static error message and icon. If an effect must flash, evaluate the actual flash rate and both relevant threshold definitions using suitable tools.'),
'2.3.2': ('A small decorative badge flashes four times per second. Its designer assumes the small area automatically makes it acceptable at AAA.', 'Remove the rapid flashing. The AAA criterion does not retain the below-threshold exception available at Level A.'),
'2.3.3': ('A settings panel zooms across the entire viewport when opened. A user sensitive to motion becomes dizzy before reaching its controls.', 'Provide a reduced-motion setting that replaces the zoom with an immediate transition. Verify that the same settings remain available.'),
'2.4.1': ('A site repeats forty navigation links before the main content on every page. A keyboard user must pass each link on every visit.', 'Add an early skip link that moves users to main content, and test its focus behavior after activation. Verify that the destination is not hidden under a sticky header.'),
'2.4.2': ('Five different application screens all show “Home” in their browser tabs. A user cannot identify the desired screen from the tab list.', 'Give each document a title that describes its purpose and update it on route changes. Compare the tabs without looking at their page bodies.'),
'2.4.3': ('A purchase dialog visually presents shipping, billing and payment in order, but keyboard focus jumps from shipping to the footer and back into payment.', 'Correct the source or focus-management order so users encounter controls in an understandable sequence. Check the sequence after the dialog opens and when it closes.'),
'2.4.4': ('A list of articles contains repeated “Read more” links without an accessible relationship to each article heading. A screen reader user cannot identify the destination.', 'Use a distinctive link name or programmatically available context, such as a meaningful structured association. Test what is announced rather than relying on visual proximity.'),
'2.4.5': ('A support article can only be reached through one deep navigation menu, and the site search never indexes it. Users who do not know the menu hierarchy may not find it.', 'Make the article reachable through another working route, such as search or a site map. Confirm the article is not merely a step or result of a process before applying the exception.'),
'2.4.6': ('A form has three controls all labeled “Details”, and a long article has headings named “More”. The labels and headings do not explain their purposes.', 'Replace them with precise names such as “Delivery address” and “Refund eligibility”. Associate each field label with its control and verify the heading structure.'),
'2.4.7': ('A stylesheet removes outlines from links and buttons and supplies only a mouse-hover color. A keyboard user cannot see which item will activate.', 'Provide a visible keyboard focus style and test it across backgrounds and browser modes. Hover styling alone does not indicate keyboard focus.'),
'2.4.8': ('A learner opens a documentation page from search and has no indication which topic and subtopic contain it.', 'Add a breadcrumb or current navigation indication that communicates location in the page set. Use appropriate semantics for the current page and test it with assistive technology.'),
'2.4.9': ('A screen reader links list contains ten links named “Read more”. Nearby article headings are not included in the list.', 'Give each link a self-contained name such as “Read the accessibility policy”. Confirm that the accessible link name still clearly identifies the destination.'),
'2.4.10': ('A long policy is presented as one uninterrupted block. Readers cannot quickly find the sections about registration, payment or cancellation.', 'Organize the writing into meaningful sections with descriptive headings. Inspect the document heading outline and check that each heading describes its following section.'),
'2.4.11': ('A sticky footer completely covers a submit button after keyboard focus moves to it. The user can activate the hidden button without seeing where focus is.', 'Adjust scrolling or overlay placement so at least part of the focused component remains visible. Retest with zoom and different viewport heights.'),
'2.4.12': ('A sticky header covers the upper half of a focused link. The link is not fully hidden, but its entire component is not visible.', 'Provide enough scroll offset or change the layout so the full focused component is visible. Test again at high zoom, where fixed regions can take up more space.'),
'2.4.13': ('A designer changes a button’s border by a barely perceptible color when it receives focus. The focused and unfocused appearances are hard to distinguish.', 'Measure the indicator area and compare the same pixels between states. Check the required perimeter-equivalent area and 3:1 change in contrast, subject to the stated exceptions.'),
'2.5.1': ('A photo viewer changes images only when a user swipes horizontally. A user operating a pointer with limited precision cannot perform the gesture reliably.', 'Add previous and next buttons that work with a single tap. Verify that they expose the same images and do not require tracing a particular path.'),
'2.5.2': ('An order is canceled as soon as the pointer touches the cancel control. An accidental press leaves no chance to move away or undo.', 'Complete the action on release while allowing the user to abort before release, or use another allowed cancellation mechanism. Test both press-and-move-away and normal activation.'),
'2.5.3': ('A button visibly says “Search”, but an overriding accessible name says “Find items”. A voice user says the visible word and cannot reliably activate the control.', 'Include the visible word in the computed name, preferably at the start, such as “Search products”. Inspect the accessibility tree and test a voice command.'),
'2.5.4': ('A mobile application undoes changes when the device is shaken, with no visible undo control and no way to turn off shake detection.', 'Add an undo button and a setting to disable shake activation. Test that normal movement cannot accidentally trigger the feature when it is disabled.'),
'2.5.5': ('A toolbar displays 16-pixel icons with equally tiny clickable regions. A user with limited pointer accuracy repeatedly activates the wrong item.', 'Expand each actual target to at least 44 by 44 CSS pixels unless an applicable exception is met. Keep the icon visually smaller if desired and verify the hit area.'),
'2.5.6': ('A tablet app detects touch on startup and disables keyboard handlers for the rest of the session. A user who alternates between touch and a hardware keyboard loses access.', 'Keep available modalities usable together unless a specified exception applies. Test switching from touch to keyboard and back without reloading.'),
'2.5.7': ('A task board moves cards between columns only by dragging. A user can tap accurately but cannot sustain and steer a drag.', 'Add a tap-operated move menu that reaches every destination. Check that the action has the same result as dragging and remains available independently of keyboard support.'),
'2.5.8': ('Adjacent 16-by-16 CSS pixel icon buttons have no spacing. A user tapping one often activates its neighbor.', 'Increase the target to 24 by 24 CSS pixels or assess the precise spacing exception. Inspect each target and its neighbors, including the specified centered circles.')
}

DEMOS = {
'2.1.1': ('<div onclick="exportReport()">Export</div>', '<button type="button" onclick="exportReport()">Export</button>', 'The native button is included in the keyboard focus order and supports standard activation. Check the exported result and any follow-up dialog too.'),
'2.1.2': ('A date picker intercepts Tab and Escape indefinitely.', 'Escape closes the picker; Tab can move to the next form control.', 'A modal may contain focus while open if it provides an operable way to close it. Confirm that closing restores a useful focus position.'),
'2.1.3': ('A drawing tool supports adding and moving shapes only by dragging.', 'Keyboard controls insert shapes, set coordinates and dimensions, and confirm placement.', 'Keyboard alternatives must offer all the underlying functionality. A menu that only selects a shape without allowing placement does not complete the workflow.'),
'2.1.4': ('document.addEventListener("keydown", e => { if (e.key === "m") mute(); });', 'Enable the character shortcut only when the player has focus, or offer disable/remap settings.', 'A global character handler can activate while someone dictates or types. Check inputs and focus changes, including settings persistence.'),
'2.2.1': ('A checkout expires after five minutes without warning.', 'Warn before expiration and let users extend with one action within at least 20 seconds; allow at least ten extensions.', 'An extension is only one option: turning the limit off or adjusting it sufficiently may also satisfy the criterion. Evaluate exceptions carefully.'),
'2.2.2': ('setInterval(nextSlide, 3000) runs with no user control.', 'Provide a Pause button that stops automatic movement; resume only when requested.', 'For auto-updating content, provide pause, stop, hide or update-frequency control. Test that controls do not merely hide the animation button.'),
'2.2.3': ('A practice form expires after 60 seconds.', 'Allow learners to submit at their own pace.', 'A timer may be displayed as information, but it must not be essential to completing the activity except within the specified exceptions.'),
'2.2.4': ('A promotion opens a modal and steals focus during form entry.', 'Offer notification preferences or postpone a non-emergency message until requested.', 'Check that deferred notifications are retrievable and that emergency alerts remain handled appropriately.'),
'2.2.5': ('Session expiry clears all unsaved form fields.', 'Save the draft safely, request sign-in, then restore the same task and data.', 'Test with a realistic expiration and avoid prematurely submitting the form. Apply appropriate data retention and privacy measures.'),
'2.2.6': ('A draft is deleted after inactivity without any warning.', 'Tell the user the inactivity duration that can cause data loss before they risk it.', 'Verify that the actual retention period matches the message; an exception applies when data remains preserved for more than 20 hours of inactivity.'),
'2.3.1': ('A large red alert flashes rapidly.', 'Show a static alert and explanatory text.', 'A pause button alone does not demonstrate conformance with flash thresholds. Evaluate the content itself with suitable analysis when necessary.'),
'2.3.2': ('A four-flashes-per-second badge is assumed acceptable because it is small.', 'Remove the rapid flashes regardless of their area for this AAA target.', 'The below-threshold exception available under 2.3.1 is not part of this enhanced criterion.'),
'2.3.3': ('.panel { transition: transform 700ms; }', '@media (prefers-reduced-motion: reduce) { .panel { transition: none; } }', 'Ensure the state change and information still work without motion. A site setting can provide additional control.'),
'2.4.1': ('A keyboard user must tab through every repeated menu on every page.', '<a href="#main">Skip to main content</a> ... <main id="main" tabindex="-1">...</main>', 'The ellipsis represents intervening page markup. Verify that activating the link moves reading position and that keyboard focus continues sensibly.'),
'2.4.2': ('<title>Home</title> appears on every route.', '<title>Payment details – Example Store</title>', 'Update document.title when client-side navigation changes the page. The title should identify the actual page or task.'),
'2.4.3': ('Positive tabindex values force focus to jump between unrelated fields.', 'Arrange controls in a meaningful DOM order and use ordinary sequential focus.', 'Test visual order, DOM order and script-driven focus at multiple viewport sizes; sequential order must preserve meaning and operation.'),
'2.4.4': ('<a href="/refund">Click here</a> without useful programmatic context.', '<a href="/refund">Read the refund policy</a>', 'Distinct link text avoids relying on surrounding context; if context is used, ensure assistive technologies can determine it programmatically.'),
'2.4.5': ('An article is reachable only through one deep menu.', 'Offer both a navigation route and a working site search or site map.', 'Verify both routes actually lead to the article. A process step or result is covered by a specific exception.'),
'2.4.6': ('<label for="email">Details</label>', '<label for="email">Email address</label>', 'A descriptive label helps users understand the input, and the for/id relationship associates it with the field.'),
'2.4.7': ('button:focus { outline: none; }', 'button:focus-visible { outline: 3px solid #003eaa; outline-offset: 2px; }', 'Check visibility against the actual surrounding colors and in high-contrast environments; do not assume the color works everywhere.'),
'2.4.8': ('Every page uses an identical menu with no current-page indication.', '<nav aria-label="Breadcrumb"><a href="/docs">Docs</a> / <span aria-current="page">Keyboard</span></nav>', 'A breadcrumb should reflect the actual hierarchy; make sure the current location is identifiable to both visual and assistive-technology users.'),
'2.4.9': ('<a href="/policy">Read more</a>', '<a href="/policy">Read the privacy policy</a>', 'Inspect a standalone links list: the accessible link text should reveal its purpose without needing the surrounding paragraph.'),
'2.4.10': ('A long document contains several topics but no section headings.', '<h2>Eligibility</h2><p>...</p><h2>How to apply</h2><p>...</p>', 'Headings organize written sections and should describe the content that follows. Keep a meaningful hierarchy rather than choosing levels only for size.'),
'2.4.11': ('A fixed footer completely covers a focused submit button.', 'html { scroll-padding-bottom: 5rem; }', 'Scroll padding can help but must match the actual overlay and be tested in real layouts, especially when zoom changes available space.'),
'2.4.12': ('A focused control is partly hidden under a sticky banner.', 'Reposition the banner or scroll until the entire focused component is visible.', 'The enhanced criterion evaluates every part of the component, not only whether some of it is visible.'),
'2.4.13': ('A one-pixel focus change is almost indistinguishable from the unfocused state.', 'Measure an indicator with area at least equivalent to a two-CSS-pixel perimeter and at least 3:1 change for the same pixels.', 'A sample two-pixel outline is only a starting point: clipping, color and the actual focused and unfocused backgrounds affect measurement.'),
'2.5.1': ('A map can zoom only through a pinch gesture.', '<button type="button" aria-label="Zoom in">+</button>', 'Connect the button to the same zoom operation and offer zoom out as well. A tap avoids a multipoint or path-based gesture.'),
'2.5.2': ('A destructive function runs on pointerdown with no abort or undo.', 'Complete on pointerup with a way to abort before completion, or provide an applicable undo.', 'Test press, move away, then release. Standard click behavior can help, but actual event handlers must not trigger the action earlier.'),
'2.5.3': ('<button aria-label="Find items">Search</button>', '<button aria-label="Search products">Search</button>', 'The computed accessible name now includes the visible label. Verify it in the accessibility tree and test a speech command.'),
'2.5.4': ('Shake device to undo, with no alternative or setting.', 'Provide an Undo button and a setting that disables shake activation.', 'The interface alternative and disable control address different barriers. Test both, unless a stated exception applies.'),
'2.5.5': ('An icon button has a 16-by-16 CSS-pixel hit area.', 'button.icon { min-width: 44px; min-height: 44px; }', 'The rendered hit area must meet both dimensions unless an exception applies. Check layout and target overlap on the actual device.'),
'2.5.6': ('A touch-start handler disables keyboard navigation for the whole session.', 'Keep touch, pointer and keyboard handlers available together.', 'A user may change inputs mid-task. Test on a hybrid device and distinguish restrictions required by security or user settings from developer convenience.'),
'2.5.7': ('A card can be moved only through drag-and-drop.', 'Provide a Move menu with tap-operated destination choices.', 'Keyboard operation is valuable, but it does not replace the single-pointer alternative required for dragging movements.'),
'2.5.8': ('button.icon { width: 16px; height: 16px; } with closely packed neighbors.', 'button.icon { min-width: 24px; min-height: 24px; }', 'If relying on spacing instead of size, evaluate the actual centered 24-pixel circles against nearby targets as specified by the exception.')
}

DEEP_DIVES = {
'2.1.1': [
 'A keyboard interface is not limited to a physical keyboard. Switch devices, speech software and other assistive technologies may generate keyboard commands. When application functionality is wired only to mouse movement or pointer clicks, those users can be blocked even though the interface works on a touch screen. Begin testing at the browser address bar and navigate the whole task without touching the mouse, so an initial mouse click does not conceal an inaccessible starting point.',
 'Native HTML controls provide a useful baseline: buttons participate in the normal tab order and implement familiar activation behavior. A link is appropriate for navigation; a button is appropriate for an action. Adding tabindex to a div only makes it focusable. It does not automatically provide the expected role, accessible name, keyboard behavior, disabled state or activation. If a complex custom widget is necessary, implement and test its complete interaction model rather than relying on focusability alone.',
 'The path-dependent exception is narrower than a drag-and-drop implementation. Rearranging cards depends on the start and end positions, so a keyboard move command can perform the underlying task. Freehand drawing may require the movement path itself; evaluate the actual function rather than applying the exception to every drawing interface. The stricter AAA criterion 2.1.3 does not include that exception.',
 'A useful test record includes the browser, operating system, starting focus, keys used, expected result and actual result. Exercise open and close controls, validation errors, dynamic results and dialog recovery. Check that focus remains visible under 2.4.7 and follows a meaningful sequence under 2.4.3; those are related criteria, not replacements for keyboard operability.'
],
'2.1.2': [
 'A keyboard trap is a focus situation from which a user cannot leave using a keyboard interface. It can isolate all later content on the page, so the impact is larger than a single broken control. Common causes include key handlers that cancel Tab, embedded widgets with incomplete keyboard support and dialogs whose close control cannot be reached or activated.',
 'Do not confuse a temporary modal focus loop with an unavoidable trap. While a properly designed modal is open, keeping focus inside can prevent interaction with content behind it. The user must nevertheless have an operable route to close or otherwise leave the modal and continue the task. A visible close button in the focus order and a functioning Escape key are common choices, although the exact design depends on the component.',
 'Test forward and backward movement using Tab and Shift+Tab. Try the documented close action, any conventional exit key and the control that originally opened the component. If leaving requires a method beyond standard unmodified arrow or Tab keys or other standard exit methods, tell users the method. Verify the instruction is available before the user becomes stuck.',
 'After closing a modal, returning focus to its opener is often helpful because it preserves location. If the opener no longer exists, place focus at a logical replacement. Also test failure paths such as validation errors and third-party content; a successful exit from the happy path does not establish that every component is escapable.'
],
'2.2.1': [
 'Time limits may be explicit, like a visible countdown, or implicit, like a session that expires while the user fills in a form. Reading with a screen reader, using a switch device, translating instructions or recovering from an interruption can all lengthen a task. A warning that appears after data is discarded cannot give the person time to respond.',
 'The criterion specifies multiple permitted approaches. An interface can let a user turn off the limit before encountering it, adjust it over a range at least ten times the default, or provide a warning with at least 20 seconds for a simple action to extend the limit at least ten times. These are alternatives; a design need not implement all three, but it must meet all conditions of whichever option it relies on.',
 'A real-time exception applies where the time limit is a required part of a real-time event and no alternative is possible. The essential exception requires that extending the limit invalidate the activity. A time limit longer than 20 hours has its own exception. Do not treat a commercial preference or a security concern as proof that an exception automatically applies; examine the exact situation and documented requirement.',
 'For a test, use a short configurable timeout in a development environment. Enter data, wait for the warning and check that the extension action is simple and keyboard operable. Measure the available response time and repeat the extension at least ten times. Confirm that the pending data survives each extension and investigate interactions with authentication or server-side expiry.'
],
'2.4.3': [
 'Focus order is the sequence in which a person reaches interactive elements using sequential keyboard navigation. It is often based on document order, but positive tabindex values, script-managed focus and visual layout techniques can produce a different sequence. A jump is a problem when it changes the meaning or prevents the user from operating the interface; a single universal left-to-right order is not required in every design.',
 'Consider a form that visually displays a label and field for name, then email, then a submit button. If keyboard focus moves from name to submit before email, the form can appear to be complete before a required field has been encountered. Similarly, when an error summary appears after submission, users need a coherent route from the summary to each invalid field and back to completion.',
 'Prefer meaningful source order and ordinary controls. Avoid using positive tabindex values to repair a broken layout because those values are difficult to maintain as components are added or removed. For dialogs, deliberately place focus where the user can understand the new context; when closing, restore it to the opener or another logical location. Do not move focus merely because a visual animation has occurred.',
 'Test at normal and increased zoom and after switching to a narrow viewport. CSS layout can change while source order remains the same. Write down the sequence in which controls receive focus, including dynamically revealed controls. Confirm that focus does not jump behind an open modal and that closing it permits the task to continue.'
],
'2.4.7': [
 'Focus identifies which interface component receives keyboard input. A visible focus indicator lets someone predict whether Enter will open a link, submit a form or activate a button. Hover and selection are different states: a pointer may hover over one element while keyboard focus is on another, and a selected item need not be the currently focused item.',
 'Browsers usually provide a default outline. Removing it globally with outline: none can erase the only position cue. If replacing a default style, provide a clear indicator for links, buttons, form inputs and custom widgets. The :focus-visible selector is useful for keyboard-oriented styling, but it should be tested in the browsers and modes the product supports.',
 'A ring can disappear when its color blends into an adjacent background or when a parent clips it with overflow: hidden. Focus styles should be tested on light and dark surfaces, over images, when controls are disabled where applicable, and at high zoom. Forced-colors modes may transform author colors, so test whether the indicator remains apparent there as well.',
 'Tab through a complete workflow and do not use the mouse to discover where you are. Record every control whose focus is ambiguous. WCAG 2.4.7 concerns the visibility of keyboard focus; the separate AAA Focus Appearance criterion has its own quantitative requirements. A style is not proven conformant simply because it uses an outline.'
],
'2.4.11': [
 'Sticky headers, fixed footers, cookie notices and chat widgets occupy screen space that ordinary document flow may not reserve. When the browser scrolls a focused control into view, that control can land underneath an overlay. A user may hear the name of a control while being unable to see it, or may activate a control whose location is unclear.',
 'The minimum criterion concerns whether the focused component is entirely hidden by author-created content. It does not mean the focus ring must be entirely visible, and it is not the same measurement as the enhanced AAA criterion, which prohibits any part of the component being hidden. Apply the criteria to the actual component and the layout that the user receives.',
 'Reserve space or adjust scroll offsets for fixed regions. CSS scroll-padding can help browsers choose a better scroll position, but a hard-coded value that works on a wide screen may fail when a banner wraps at higher zoom. Check the actual overlay height, resize behavior and dynamic opening of notices. A CSS declaration by itself is not proof that the control is visible.',
 'Start at the top of a long page and tab through every control near the bottom edge. Repeat with increased zoom, a narrow viewport and any author-provided notice open. Note whether the entire focused component is covered. When user-opened content can be dismissed or moved without advancing focus, account for the relevant criterion notes in the test.'
],
'2.5.1': [
 'A multipoint gesture uses more than one point of contact, such as pinching a map. A path-based gesture depends on moving through a particular path, such as swiping a carousel or tracing a shape. Some users can tap but cannot reliably coordinate multiple fingers or maintain a precise movement, particularly when using a head pointer or other pointing aid.',
 'Provide the same function through a single pointer without requiring a path-based gesture, unless that gesture is essential. For a map, plus and minus buttons can offer the same zoom operation. For a gallery, previous and next buttons can show the same set of images. Merely adding an explanation of the swipe does not supply an alternative operation.',
 'Separate the gesture requirements from keyboard requirements. A keyboard shortcut can be a valuable additional method but it does not by itself offer a single-pointer alternative. Conversely, a tap-operated button should still be made keyboard accessible when other applicable criteria require it. Check labels, target size and pointer cancellation in addition to the gesture itself.',
 'Test with a mouse or one finger: without dragging, swiping or using a second contact point, perform every action that the gesture offers. Compare the outcomes and range of available values. If the gesture is asserted to be essential, explain why the underlying function cannot be achieved another way rather than treating the existing implementation as the definition of the task.'
],
'2.5.7': [
 'Dragging requires a user to press, move while maintaining contact and release at an intended position. This can be difficult when a user has tremor, limited dexterity, an imprecise pointer or a device that cannot conveniently maintain a drag. A board may seem usable because its cards are visible and clickable, yet moving them may still be impossible.',
 'The criterion requires functionality that uses dragging to be achievable with a single pointer without dragging, unless dragging is essential or the functionality is determined by the user agent and not modified by the author. A menu of destination columns, a move-up and move-down control, or a click-source then click-destination workflow can provide an alternative. It must support the same meaningful result.',
 'Do not confuse this with keyboard access. A reorderable list with excellent arrow-key support can still lack the required non-dragging pointer operation. Similarly, a tap control that only moves an item one position when dragging supports arbitrary destinations should be evaluated for whether users can actually reach all the same destinations through repeated operations.',
 'Test the full task using a mouse or touch pointer without holding a button while moving. Move an item to the first, last and an intermediate position; confirm that the new order is saved and communicated. Repeat after errors or when an item cannot be moved. Keep any feedback understandable without relying solely on animation.'
],
'2.5.8': [
 'A pointer target is the area that accepts the input, not necessarily the visible icon. A tiny icon can sit inside a larger clickable button, while a large visual graphic can still have an unexpectedly small interactive region. Users with limited accuracy may miss a target or activate its neighbor, especially on touch devices.',
 'The general AA minimum is 24 by 24 CSS pixels. The criterion includes specific exceptions for spacing, equivalent targets, inline targets, unmodified user-agent controls and essential presentation. The spacing exception is precise: center a 24-CSS-pixel-diameter circle on each undersized target bounding box and assess intersections with other targets or the circles of other undersized targets. A vague claim that buttons are “far enough apart” is not a measurement.',
 'The equivalent exception depends on another control on the same page that achieves the same function and meets the criterion. An inline link in a sentence is handled differently because line height can constrain it; this is not permission to shrink every button placed near text. Some presentation is essential or legally required, so examine the actual exception rather than labeling an inconvenient design essential.',
 'Use browser developer tools to measure rendered hit areas in CSS pixels and inspect adjacent controls. Test at several zoom levels and with a touch pointer. For an undersized target, draw or calculate the relevant circles and check each neighboring target. The separate AAA enhanced criterion normally uses 44 by 44 CSS pixels and different exceptions.'
]
}

DEEP_DIVES.update({
'2.1.3': [
 'Level A keyboard support has an exception for functions where the underlying operation genuinely depends on the path of movement. This AAA criterion removes that exception. A gesture used as a convenient input method should not be confused with a function that is intrinsically path-dependent: sorting cards, for example, has identifiable start and end positions.',
 'For a graphic editor, list each operation rather than checking only whether menus open: create a shape, select it, move it, adjust dimensions and rotation, edit its properties and delete it. A keyboard interface might use numeric fields, selection controls and commands. Check that those controls can produce the same outcomes, not just approximate a subset.',
 'Test without relying on timed key sequences. Document whether every action is achievable and whether the user receives appropriate feedback. This AAA target may require substantial design work for freehand or path-based activities; avoid claiming full coverage merely because a few keyboard shortcuts exist.'
],
'2.1.4': [
 'A character key shortcut consists only of printable letters, numbers, punctuation or symbols. Speech input can accidentally trigger it when dictated words are interpreted as commands; a keyboard user may also activate it while typing if the page handles keystrokes globally.',
 'Three safeguards are available: allow users to turn the shortcut off, let them remap it to include a non-printable modifier such as Ctrl or Alt, or make the shortcut active only while the relevant component has focus. A shortcut limited to a focused component must actually remain inactive outside that focus context.',
 'Test a shortcut while a text field is focused and while focus is elsewhere. If remapping is provided, check for conflicts, communicate the new combination and verify it persists as intended. Do not silently suppress ordinary typing or rely on a user remembering to avoid a particular character.'
],
'2.2.2': [
 'Motion and automatically changing content can compete for attention or prevent users from reading at their own pace. The criterion addresses two cases with different conditions. Automatically moving, blinking or scrolling content presented alongside other content needs a control when it lasts more than five seconds, unless the motion is essential. Automatically updating content presented alongside other content also needs a control, but the five-second condition does not apply to that case.',
 'The offered mechanism can pause, stop or hide qualifying movement. For auto-updates, controlling the update frequency is another option. Place the control where users can find and operate it without having to chase the moving item; give it a meaningful label and ensure its state matches what it does.',
 'A pause may not need to replay every update that occurred while the content was paused; in a live stream that may not be technically possible or may be misleading. Test that the pause genuinely stops the relevant change, that the rest of the page remains usable and that the chosen behavior makes sense when updates resume.'
],
'2.2.3': [
 'This AAA criterion addresses whether timing is essential to an activity. It is stronger than 2.2.1, which permits specific adjustment or extension mechanisms. A learner might still feel pressured by a countdown even if several extensions are available.',
 'For a practice task, allow the learner to read, think and answer without a deadline determining success. If timing is used for analysis, consider showing elapsed time while preserving the ability to complete the task at any pace. Timing is not automatically essential just because the original design included a timer.',
 'The criterion specifies exceptions for non-interactive synchronized media and real-time events. An actual live auction is different from a recorded tutorial or self-paced form. Review the underlying activity, identify whether the exception applies, and test the entire task without a deadline.'
],
'2.2.4': [
 'An interruption redirects attention away from the user’s chosen task. A pop-up promotion, automatic chat invitation or forced update can interrupt a screen reader announcement or break concentration during a complex form. A message the user explicitly opened is different from an unsolicited interruption.',
 'Give users control to postpone or suppress non-emergency interruptions. Preferences might include a quiet mode, a notification center or a deferred prompt. Do not move keyboard focus to a non-emergency message while the person is typing, and provide a reasonable way to find postponed information when it is relevant.',
 'Emergency interruptions are an exception. Test by starting a form, triggering ordinary notifications and checking that the user can defer or prevent them while continuing the same task. Verify that the setting affects the actual interruption rather than only muting a sound.'
],
'2.2.5': [
 'Authentication sessions protect accounts, but expiration can happen while a user is composing an answer or gathering information. Losing their work can disproportionately affect users who need longer to read, enter text or use assistive technology.',
 'The requirement is to continue the activity without loss of data after re-authentication. This is more than returning to the same URL: answers, selected options and the current step may need to be restored. Preserve only the necessary information using storage and retention appropriate to the application, user expectations and privacy obligations.',
 'In a test environment, expire the session after entering distinctive values, sign in again and verify that the user returns to the unfinished task. Check that the restoration does not submit or share the draft unexpectedly. Consider what happens if re-authentication fails or is canceled and communicate the next step.'
],
'2.2.6': [
 'Users should know how long inactivity can cause data to be lost before relying on the application to keep a draft. A timeout may differ from session expiry: an account can remain signed in while an unsaved draft is removed, or a session can expire while a draft remains preserved.',
 'State the relevant period in language that matches actual behavior. If inactivity of fifteen minutes discards entered answers, tell the user that before the loss occurs. The criterion provides an exception when the data is preserved for more than 20 hours of inactivity; exactly 20 hours does not meet that wording.',
 'Test the server behavior, not only a countdown shown in the interface. Enter data, stop interacting for the documented period and verify what remains. Consider privacy and consent when retaining drafts, especially on shared devices; preserving data longer should be designed deliberately rather than assumed to be risk-free.'
],
'2.3.1': [
 'Flashing involves alternating changes in luminance that can trigger photosensitive seizures. Certain saturated red flashes receive particular attention in the threshold definitions. Large, rapid flashes can be hazardous even when the rest of a page is accessible.',
 'The Level A rule permits no more than three flashes in any one-second period, unless the flashing falls below the specified general and red flash thresholds. Those thresholds are not a simple guess about whether a graphic looks small. Assess the actual rendered content, including video, animated advertisements and overlays, with an appropriate analysis method.',
 'The safest ordinary design is to avoid rapid flashes: use stable text, a static icon or a non-flashing status change. A pause control does not by itself establish that hazardous content meets the flash requirement. The related AAA 2.3.2 removes the threshold alternative.'
],
'2.3.2': [
 'At AAA, a page must not contain anything that flashes more than three times in any one-second period. Unlike 2.3.1, this rule does not permit more frequent flashes merely because they fall below the general and red thresholds.',
 'Review advertisements, video, progress effects and error treatments, not just the application’s own CSS. Replace rapid flashing with stable feedback wherever possible. A warning that appears before flashing does not remove the flashing from the page.',
 'Analyze an actual representative second of rendered content using the WCAG definition of a flash and suitable tools. An animation can contain bright changes that are not automatically equivalent to flashes, so count based on the definition rather than guessing from the number of frames.'
],
'2.3.3': [
 'Motion triggered by interaction can produce dizziness or nausea for some users. Examples include a large panel flying across the screen after a button press, parallax movement during scrolling and animated zoom transitions. This AAA requirement concerns motion animation triggered by interaction, with an exception when it is essential to the function or information.',
 'Allow the animation to be disabled while keeping the result available. Respecting the operating system’s reduced-motion preference is a useful technique; an application-specific preference can also give users control. Replacing motion with an immediate state change or a subtle non-motion cue preserves the action without requiring the same visual effect.',
 'Test with the preference enabled and disabled, including menus, dialogs, scrolling and route changes. Verify that disabling animation does not remove the destination, feedback or control. Separately assess automatic movement under 2.2.2 and flashing under 2.3.1; one setting does not settle every motion-related criterion.'
],
'2.4.1': [
 'Repeated blocks such as site navigation, promotional links and account controls appear on many pages. A person navigating by keyboard or linear reading may otherwise traverse the same material repeatedly before reaching the content that changes.',
 'A skip link near the beginning of the page can point to the main content. Its destination needs a valid unique identifier, and the link must be available to keyboard users. A link that remains invisible when focused or points to a nonexistent target is not a useful bypass. Semantic landmarks and other methods can also provide navigation mechanisms; test the method in the supported environment.',
 'Load a page from the browser address bar, press Tab and activate the bypass. Verify that the user reaches the intended main region and can continue navigating from there. Repeat on pages with sticky headers and different layouts, because the destination may otherwise be obscured or the subsequent focus order may return to the navigation.'
],
'2.4.2': [
 'A document title appears in browser tabs, history, bookmarks and assistive technology. It gives a user an early way to distinguish the current page from other open pages. A visible heading alone does not replace a descriptive browser title.',
 'Choose a concise title that identifies the page topic or purpose, usually followed by the site or application name. For multi-step flows, distinguish steps such as shipping and payment. For single-page applications, update the document title when navigation changes the page content; the browser tab should not remain stuck on the initial route.',
 'Open several routes in separate tabs and read only their titles. Confirm that each is recognizable and that title changes follow navigation. If a form returns an error page, a title that identifies the error state may help users notice the change, while preserving the underlying page context.'
],
'2.4.4': [
 'A link’s purpose should be clear from its text alone or from text together with its programmatically determined context, except where the purpose would be ambiguous to users generally. Visual proximity is not necessarily programmatic context: assistive technology needs the relationship to be represented by the document structure.',
 'Descriptive link text is often the simplest solution. A link labeled “Read the refund policy” conveys more than “Click here”. In a list or table, surrounding structured context can sometimes establish the purpose, but repeated generic links still place extra demands on people who use a links list or navigate quickly.',
 'Inspect links in context and through assistive technology. Check that identical names do not unexpectedly lead to different destinations without adequate context, and that the accessible name reflects what the link does. The AAA criterion 2.4.9 sets a stronger target for link text alone.'
],
'2.4.5': [
 'Users search for information in different ways: some follow menus, others use search or a site map, and some arrive through contextual links. Providing more than one way to locate pages reduces dependence on remembering a single hierarchy.',
 'The criterion applies to locating a web page within a set of web pages, with an exception for a page that is a step in or the result of a process. For example, a final confirmation screen may be tied to completing a transaction; that differs from a publicly available help article.',
 'Pick several representative pages and trace two distinct working routes. Search must return the intended content, not merely be present as a decorative field. Test the routes with keyboard and verify that permissions or broken links do not make one route unusable.'
],
'2.4.6': [
 'Headings and labels describe the purpose of sections and fields. A heading such as “Details” may be too broad when several sections contain different kinds of details; a label such as “Input” does not tell the user what information to enter.',
 'Write labels that identify the expected information, such as “Delivery address” or “Email address”. Associate each label programmatically with its field so that clicking the label and using assistive technology identify the same control. Use headings that describe the following section rather than relying on size or color alone.',
 'Review the interface without relying on surrounding visual cues. Ask whether each heading accurately describes its section and whether each field label distinguishes it from similar fields. This criterion addresses the descriptive quality of headings and labels; other criteria cover their programmatic relationships and instructions.'
],
'2.4.8': [
 'At AAA, users have information about their location within a set of web pages. Someone arriving through a search engine may not know which section contains the page or how to reach related material.',
 'A breadcrumb, current item in a consistent navigation system, or another location cue can provide this information. A breadcrumb should reflect a meaningful site hierarchy and identify the current location. When appropriate, use aria-current to communicate the current page programmatically.',
 'Navigate directly to a deep page and check whether the location cue is understandable without first visiting its parent. Then follow the parent link and confirm the indication updates. Do not confuse the current focus indicator with the current page indication: one identifies keyboard position, the other location in the site.'
],
'2.4.9': [
 'Some screen reader users navigate a list of links detached from the surrounding paragraphs. Repeated “More” links can become indistinguishable even if a visual reader can infer their destinations from nearby headings.',
 'The AAA criterion requires a mechanism to identify purpose from link text alone, except where that purpose would be ambiguous to users generally. Write self-contained names such as “Read the admission requirements” or “Download the 2025 report”. Ensure the accessible name and the visible wording work together.',
 'Generate or inspect a links list and ask what each entry does without reading its paragraph. Check duplicate names that lead to different resources and verify file format or destination details where they are relevant to user choice. The related A criterion 2.4.4 permits programmatically determined context.'
],
'2.4.10': [
 'Section headings help readers identify the organization of written material and jump to a relevant topic. A large wall of text requires more sustained reading and makes it harder to locate a particular step or policy.',
 'Use headings for meaningful sections rather than inserting them solely to increase font size. Semantic heading elements can expose an outline to assistive technology; use levels that reflect the document structure. A heading should match the content that follows and avoid repeating the same vague word for unrelated sections.',
 'This criterion concerns sections within writing, not the names of user interface components. Inspect a long article’s heading list independently of its body. Verify that the list conveys the article’s structure and that users can find the relevant section without reading every paragraph.'
],
'2.4.12': [
 'The enhanced AAA focus-obscuration criterion requires that no part of a focused component be hidden by author-created content. This is stricter than the AA minimum, where the failure concerns a component that is entirely hidden.',
 'Fixed headers, banners and floating widgets are common sources of partial coverage. At high zoom a banner may grow taller or wrap, so an offset that works at a normal viewport may no longer protect the whole control. Treat both horizontal and vertical clipping as layout questions to inspect.',
 'Tab through controls near each fixed region and inspect the complete bounding area of the focused component. Adjust the layout or scrolling behavior so that the whole component is visible. Also verify the focus indicator itself under the applicable focus visibility requirements.'
],
'2.4.13': [
 'A focus indicator needs enough visible change for users to distinguish focused and unfocused states. The AAA criterion measures an indicator area and a contrast change; it should not be reduced to a recommendation that every element use an arbitrary border.',
 'The qualifying area must be at least the area of a two-CSS-pixel-thick perimeter of the unfocused component or subcomponent, and it must have at least 3:1 contrast between the same pixels in the focused and unfocused states. The criterion has exceptions for certain user-agent-determined or author-unmodified indicators.',
 'Measure the rendered component and indicator, accounting for clipping, overlaps and the state before focus. Compare the same pixels in both states; a color that contrasts with a neighboring background does not automatically prove the required state change. Test actual widgets and viewport conditions rather than assuming a CSS outline declaration is always sufficient.'
],
'2.5.2': [
 'When an action completes on the down event, a person who touches the wrong control may have no opportunity to correct the mistake. Completing an ordinary operation on release can let the user move away before releasing, preventing accidental activation.',
 'The criterion provides multiple alternatives, including not using the down event to execute any part of the function, completing on up with an abort or undo mechanism, reversing the down-event outcome on up, or an essential-function exception. Evaluate the complete behavior; merely adding a click listener is not enough if a separate pointerdown handler already performs the destructive action.',
 'Press and hold the control, move away and release; verify the resulting action. Then activate normally and test any undo. Consider touch, mouse and assistive pointing devices. Some controls that emulate a keyboard or numeric keypad press have an essential-operation note, so inspect the specific function rather than assuming every press must work identically.'
],
'2.5.3': [
 'Speech input users often identify an on-screen control by speaking its visible label. If an author overrides its accessible name with unrelated words, the command may not match what the user sees. This mismatch can also make collaboration between sighted and assistive-technology users confusing.',
 'For a control with a visible text label or image of text, ensure that its accessible name contains that visible text. A useful convention is to place the visible text at the beginning, followed by clarifying information where needed. For example, “Search products” contains the visible label “Search”.',
 'Inspect the computed accessible name, including any aria-label or aria-labelledby that overrides text content. Compare the visible text and the announced name and try a voice command using the visible wording. Do not assume that a visually obvious icon supplies the same name to assistive technology.'
],
'2.5.4': [
 'A feature may respond to motion of a device, such as shaking a phone, or motion of a user, such as a gesture detected by a camera. Some users cannot perform the motion, while others may trigger it accidentally during ordinary movement.',
 'Provide an alternative user interface component and let users disable responding to the motion, unless an applicable supported-interface or essential exception applies. A conventional Undo button can accompany shake-to-undo, and a preference can turn shake detection off. These address different needs: accessibility of the operation and prevention of accidental activation.',
 'Test the alternative without moving the device and test that disabling motion prevents accidental activation. Review whether the claimed exception actually applies; a motion that is merely convenient or entertaining is not necessarily essential to the task.'
],
'2.5.5': [
 'The enhanced AAA target-size criterion generally requires pointer targets to be at least 44 by 44 CSS pixels. The target is the clickable or tappable area, which may be larger than the visual icon. This larger area helps people who have difficulty making precise movements.',
 'The criterion includes specific exceptions, including an equivalent target on the same page, inline targets, unmodified user-agent controls and essential presentation. The AA minimum-size criterion has its own requirements and exceptions; do not assume its spacing exception automatically satisfies this AAA criterion.',
 'Inspect the actual rendered hit area using browser tools and try activating adjacent controls on a touch device. Enlarging padding can improve the target without enlarging the icon, but check that nearby controls do not overlap and that layout remains usable at zoom.'
],
'2.5.6': [
 'Many devices support several input methods at once. A person may use a touchscreen for broad navigation, a hardware keyboard for text, and a pointing device for a precision task. A site that chooses one mode at startup can prevent the user from changing methods when their circumstances change.',
 'At AAA, content does not restrict platform input modalities except where restriction is essential, needed for content security, or required by user settings. Touch detection should generally enable touch support without disabling keyboard or mouse handling. Respect explicit user settings and assess genuine security restrictions separately.',
 'Test on a hybrid device in one continuous session: activate a menu by touch, enter text by keyboard and use a pointer on another control. Confirm that switching does not require reloading and does not erase the current task. Check both author scripts and any third-party widgets.'
]
})

VERIFICATION = {
'2.1.3': 'In a diagram editor, list every available operation before testing: creating an object, changing its shape, positioning it, editing its label, and deleting it. Try each operation with the keyboard. A keyboard-accessible toolbar is insufficient if the only way to place the selected object is to trace a pointer path. Record missing operations separately from focus problems, because reaching a control does not prove the whole task can be completed.',
'2.1.4': 'Test a shortcut in three contexts: the intended component has focus, a text field has focus, and focus is elsewhere on the page. A shortcut limited to the component should activate only in the first case. If a preference disables or remaps it, reload the application and check whether the preference is retained. Also verify that the revised shortcut does not interfere with typing or another essential command.',
'2.2.2': 'Do not confuse stopping an animation with stopping changing information. For a carousel, pause movement and verify the current slide stays still. For a live feed, record its contents, pause updates, wait through at least one update interval, and check that new items do not interrupt reading. If updates resume, explain whether the feed catches up or starts from the latest state so users can make an informed choice.',
'2.2.3': 'Distinguish a deadline that controls task completion from a clock displayed for reference. A self-study exercise can show elapsed time while still accepting answers indefinitely. Test by leaving it idle beyond the former deadline, returning, changing an answer, and submitting. A live event may involve timing that is inherent to its real-world operation; the fact that a product owner prefers a deadline does not by itself make timing essential.',
'2.2.4': 'Interruptions include more than dialog boxes: sounds, banners, and notifications can divert attention while someone reads or types. Offer a preference to postpone or suppress non-emergency interruptions, and verify it with an interruption triggered during a task. Check that the current focus and entered text remain intact and that the user can later find deferred information. Keep emergency messages distinguishable from ordinary promotions.',
'2.2.5': 'Test the session-expiry path with realistic unfinished work rather than an empty form. Enter several values, allow the session to expire, reauthenticate, and compare the restored values and current step with the state before expiry. Confirm that restoration does not silently submit the application. Protect drafts on shared devices and decide how long they are retained; preserving data must not accidentally expose it to another person.',
'2.2.6': 'A useful warning identifies the period of inactivity and the consequence, for example: “Your unsaved answers will be deleted after 15 minutes of inactivity.” Place this information before users risk losing work, and verify it against the actual retention behavior. A warning that says only “session expires soon” does not explain that answers may be lost. Test both the stated duration and any longer-than-20-hours preservation exception.',
'2.3.1': 'When evaluating a flashing video, examine the rendered content over time rather than checking only a still image. The general and red-flash thresholds depend on technical characteristics, including affected area, and both must be considered when relying on the threshold exception. A pause control does not prevent exposure before it is found. If the visual effect is unnecessary, removing the flash is a more straightforward design.',
'2.3.2': 'Compare this enhanced requirement with the Level A criterion before evaluating a small flashing icon. At Level A, a sequence may fall below the relevant thresholds even if it flashes more than three times per second. For this AAA criterion, that below-threshold alternative is not available. Review advertisements and embedded videos as well as application-owned animation, and inspect any one-second interval rather than averaging over a whole clip.',
'2.3.3': 'Test the preference before opening the interface, because a user should not have to experience the problematic animation in order to disable it. With reduced motion enabled, trigger the same menu, route change, and dialog as in the default mode. Verify that content appears in the correct place and that focus is still managed. A brief opacity change may be less disruptive than large movement, but user controls and the actual effect still need evaluation.',
'2.4.1': 'Start at the browser address bar, move focus into the page, and look for the bypass control before navigating through repeated links. Activate it and check both the visible destination and the next Tab stop. A link that scrolls to the main region but leaves sequential focus among the navigation links may not provide the expected keyboard experience. Repeat on a second page with the same navigation and with a sticky header present.',
'2.4.2': 'Compare pages by using only their browser tabs or history entries. A title such as “Account” repeated for profile, security, and billing pages does not distinguish those tasks. Use titles that describe the current page and keep the site name as supporting context. In a single-page application, navigate without reloading and verify that the document title changes when the route changes, including when using the browser Back button.',
'2.4.4': 'A link’s purpose may be determined from its text together with programmatically determined context under the stated conditions. Visually placing an article heading beside “Read more” does not automatically establish that association. Inspect the structure with a screen reader and compare how the link is announced in context. If context is unreliable or ambiguous, use a more specific label such as “Read the course registration guide.”',
'2.4.5': 'Create an inventory of representative pages and record the routes users can take to reach each one. Search is a second method only if its index includes the page and its result actually opens it. Test navigation with the keyboard as well. A checkout confirmation or another page that is a step or result of a process has a specified exception; do not treat a normal help article as a process step simply because it links from a form.',
'2.4.6': 'Ask a reviewer to scan the headings and field labels without reading the surrounding paragraphs. If several unrelated sections are called “Details,” the page gives little help in choosing a destination. Replace vague wording with labels tied to the actual task, then inspect the programmatic association between each label and input. A placeholder alone can disappear during entry and should not be relied on as a persistent label.',
'2.4.8': 'A breadcrumb can show a path such as “Documentation > Forms > Error messages,” with the final item identifying the current page. Check that its hierarchy corresponds to the actual site structure and that earlier items navigate to meaningful parent pages. A current item in navigation is another possible location cue. Location within the site is different from the browser title: users need a way to understand where the current page sits among related pages.',
'2.4.9': 'At the enhanced level, test the link text itself without relying on surrounding programmatically determined context. Open a screen reader links list and compare repeated names: ten links called “Read more” provide no distinction even when each is next to a different heading in the page. Revise each accessible link name to identify its destination, while keeping any visible label and accessible name compatible for speech input.',
'2.4.10': 'Take a long guide and divide it where its subject or task changes, such as eligibility, application steps, and appeals. Give each section a heading that previews the content below it. Use real heading semantics so a screen reader can expose the hierarchy. Then scan the headings without the body: a reader should be able to predict where to find a topic. Decorative bold text alone may not communicate the same structure.',
'2.4.12': 'Test at several viewport heights and zoom levels, because a fixed banner that covers only a few pixels at one size can hide half a control at another. Focus each control near an overlay and inspect all edges of the component, not just its label or focus ring. Consider scroll margins, repositioning the overlay, or reducing fixed content. Retest after a banner wraps or the virtual keyboard changes the available viewport.',
'2.4.13': 'Capture focused and unfocused states at the same scale, then compare the pixels occupied by the indicator between those states. The area and contrast-change requirements are distinct: a large indicator with too little state contrast is not sufficient, and a tiny high-contrast mark may not have sufficient area. Include clipping by neighboring elements in the inspection and account for the criterion’s exceptions before reporting a failure.',
'2.5.2': 'Reproduce an accidental press by pressing a control, holding, moving the pointer outside it, and releasing. Observe whether the action still occurs. For an action completed on release, provide an abort or undo as specified by the criterion; if the action already happens on pointer down, check whether release reverses it or another permitted condition applies. Test destructive actions with reversible sample data so the behavior can be observed without harming real records.',
'2.5.3': 'Inspect the computed accessible name in browser developer tools, because aria-label or aria-labelledby can replace what is announced. If a button displays “Send” but is named “Submit message,” a speech user may say the visible word and fail to activate it. “Send message” preserves the visible wording and adds context. Repeat the comparison after localization and when labels change dynamically, not only in the default language and state.',
'2.5.4': 'Exercise both parts of the solution independently. First perform the task using the visible control without moving the device or user’s body. Then turn off motion activation and confirm that shaking or the monitored gesture no longer triggers the action accidentally. If claiming that movement is essential or supported through an accessibility interface, document why the actual feature qualifies rather than assuming all motion features are exempt.',
'2.5.5': 'Measure the interactive hit area in CSS pixels, including padding, rather than measuring only the painted icon. Check adjacent targets at normal size and zoom: a large invisible target that overlaps a neighbor can create a different activation problem. If relying on an exception, identify its precise conditions and test the proposed equivalent target. The smaller minimum-size requirement and its spacing exception should not be substituted for this enhanced target.',
'2.5.6': 'On a convertible device, begin a task using touch, continue by keyboard, and finish with a mouse or trackpad without reloading. Check that touch detection has not removed keyboard focus or disabled pointer events. Repeat in embedded widgets, which may use separate event handling. An author may need a restriction for an essential function, security, or user settings, but a device being touch-capable alone is not such a reason.'
}

def paragraph(text):
    return {'type': 'paragraph', 'content': [{'type': 'text', 'text': text}]}

def heading(text):
    return {'type': 'heading', 'attrs': {'level': 2}, 'content': [{'type': 'text', 'text': text}]}

def codeblock(text):
    return {'type': 'codeBlock', 'content': [{'type': 'text', 'text': text}]}

def question(name, prompt, correct, distractors):
    choices = [correct, *distractors]
    offset = int.from_bytes(hashlib.sha256(prompt.encode('utf-8')).digest()[:2], 'big') % len(choices)
    choices = choices[offset:] + choices[:offset]
    return {'type': 'radiogroup', 'name': name, 'title': prompt,
            'choices': choices, 'isRequired': True}

def exam(title, rows):
    elements = [question(f'q{i}', row[3], row[4], row[5]) for i, row in enumerate(rows, 1)]
    return {'questions': {'title': title, 'pages': [{'name': 'page1', 'title': 'Knowledge check', 'elements': elements}]},
            'answer_key': {f'q{i}': row[4] for i, row in enumerate(rows, 1)},
            'explanations': {f'q{i}': row[1] for i, row in enumerate(rows, 1)},
            'passing_percent': 70, 'max_attempts': 3}

def mini_exam(title, code, row):
    result = exam(title + ' mini-assessment', [row])
    problem, remedy = SCENARIOS[code]
    elements = result['questions']['pages'][0]['elements']
    elements.append(question('q2', problem + ' What should the team do?', remedy, row[5]))
    elements.append({'type': 'boolean', 'name': 'q3',
                     'title': 'True or false: The following is an appropriate response to this problem: ' + row[5][0] + '.', 'isRequired': True})
    result['answer_key'].update({'q2': remedy, 'q3': False})
    result['explanations'].update({'q2': row[1], 'q3': row[1]})
    return result

reference = next(x for x in json.loads(REFERENCE.read_text(encoding='utf-8-sig')) if x['principle'] == 'Operable')
criteria = [criterion for group in reference['lessons'] for criterion in group['sublessons']]
lessons = []
for criterion in criteria:
    title, level = criterion['title'], criterion['level']
    code = title.split()[0]
    concept, implementation, activity, prompt, answer, wrong = NOTES[code]
    objective = f'Explain WCAG {title} (Level {level}), identify the barrier it addresses, and apply and test an appropriate solution.'
    problem, remedy = SCENARIOS[code]
    bad, good, explanation = DEMOS[code]
    content = {'type': 'doc', 'content': [heading('Learning objectives'), paragraph(objective),
        heading('The accessibility problem'), paragraph(concept),
        heading('Implementation and testing'), paragraph(implementation),
        heading('Real-world example: the barrier'), paragraph(problem),
        heading('Improved design and verification'), paragraph(remedy),
        heading('Implementation demonstration'), paragraph('Problematic approach:'), codeblock(bad),
        paragraph('Improved approach:'), codeblock(good), paragraph(explanation),
        *([heading('Detailed guidance')] + [paragraph(text) for text in DEEP_DIVES[code]] if code in DEEP_DIVES else []),
        *([heading('Worked verification')] + [paragraph(VERIFICATION[code])] if code in VERIFICATION else []),
        *([heading('Further explanation and testing')] + [paragraph(text) for text in EXPANDED_NOTES[code]] if code in EXPANDED_NOTES else []),
        *([heading('Applied review exercise')] + [paragraph(PRACTICAL_REVIEWS[code])] if code in PRACTICAL_REVIEWS else []),
        *([heading('Implementation review')] + [paragraph(IMPLEMENTATION_REVIEW[code])] if code in IMPLEMENTATION_REVIEW else []),
        heading('Worked example and edge cases'), paragraph(CASES[code]),
        heading('Planning a thorough review'),
        *[paragraph(text) for text in FAMILY_GUIDANCE['.'.join(code.split('.')[:2])].split('\n\n')],
        heading('Required practical activity'), paragraph(activity),
        heading('Knowledge check'), paragraph(prompt),
        heading('Key takeaway'), paragraph('Test the outcome with the relevant input methods and users; a visual change or a single automated test does not by itself establish conformance.') ]}
    lessons.append({'title': title, 'objective': objective, 'content': content,
                    'assessment': mini_exam(title, code, NOTES[code])})
assert set(NOTES) == {item['title'].split()[0] for item in criteria}
assert set(DEMOS) == set(NOTES) == set(SCENARIOS)
pre_codes = ('2.1.1','2.2.1','2.3.1','2.4.3','2.4.7','2.5.1','2.5.3','2.5.7','2.5.8')
titles = {item['title'].split()[0]: item['title'] for item in criteria}
all_codes = list(titles)
selection = []
for k in pre_codes:
    i = all_codes.index(k)
    distractors = [titles[all_codes[(i + delta) % len(all_codes)]] for delta in (1, 2, 3)]
    selection.append((NOTES[k][0], NOTES[k][1], NOTES[k][2],
                      'Which success criterion addresses this situation? ' + NOTES[k][0],
                      titles[k], distractors))
post_codes = ('2.1.2','2.2.2','2.3.3','2.4.1','2.4.4','2.4.11','2.5.2','2.5.4','2.5.7')
post_rows = [(NOTES[k][0], NOTES[k][1], NOTES[k][2],
              'A reviewer finds this approach: ' + DEMOS[k][0] + ' Which change best addresses it?',
              DEMOS[k][1], NOTES[k][5]) for k in post_codes]
output = {'principle': 'Operable', 'lessons': lessons, 'pre': exam('Operable pre-assessment', selection),
          'post': exam('Operable post-assessment', post_rows)}
(HERE / 'operable.json').write_text(json.dumps(output, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
